import{_ as t,o,c as a,ag as i}from"./chunks/framework.44aEvdQQ.js";const f=JSON.parse('{"title":"Labor Efficiency Ratio - The Math Behind the Philosophy","description":"","frontmatter":{"title":"Labor Efficiency Ratio - The Math Behind the Philosophy","order":10},"headers":[],"relativePath":"about/chapters/10-labor-efficiency-ratio-the-math-behind-the-philosophy.md","filePath":"about/chapters/10-labor-efficiency-ratio-the-math-behind-the-philosophy.md"}'),s={name:"about/chapters/10-labor-efficiency-ratio-the-math-behind-the-philosophy.md"};function r(n,e,h,l,c,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<h3 id="_10-labor-efficiency-ratio-the-math-behind-the-philosophy" tabindex="-1">10.<br>Labor Efficiency Ratio - The Math Behind the Philosophy <a class="header-anchor" href="#_10-labor-efficiency-ratio-the-math-behind-the-philosophy" aria-label="Permalink to &quot;10.&lt;br&gt;Labor Efficiency Ratio - The Math Behind the Philosophy&quot;">​</a></h3><h4 id="crabtree-s-framework-as-business-scaffolding" tabindex="-1">Crabtree’s Framework as Business Scaffolding <a class="header-anchor" href="#crabtree-s-framework-as-business-scaffolding" aria-label="Permalink to &quot;Crabtree’s Framework as Business Scaffolding&quot;">​</a></h4><p>It&#39;s often said that all time tracking is a lie, but a useful lie. Although recording time has always been a chore does not mean we cannot get closer to the goal of better understanding ourselves.</p><p>Discovering Greg Crabtree&#39;s Labor Efficiency Ratio is one of those <em>aha</em> moments that helps reduce the complexity of running a small business that hinges on the cost of labor. The goal is not to reduce the cost of people at any expense, but to better understand our needs, what we can afford to pay people as a business, and to increase our control over the number that dominates small business strategy. You need your gross profit number to be three times larger than the total you pay people to do the work.</p><p>LER offers us a compass to use in (very) difficult conversations each owner must face:</p><ul><li>Our senior employees must pull their weight</li><li>We must invest in affordable junior talent</li><li>Atrophying loyalty is measurable liability</li></ul><p>The equilibrium: people doing work ↔ gross profit generated. Simple Numbers framework as second paradigm alongside EOS. Why LER success in the case study (40% salary reduction, -15% to +25% profit margin over 2 years).</p><blockquote><p>Parkinson’s Law dictates that &quot;work expands so as to fill the time available for its completion&quot;</p></blockquote><blockquote><p>Nothing of value happens without labor productivity. Labor efficiency is the number one driver of profitability.</p><p><em>Simple Numbers. Straight Talk, Big Profits!</em></p></blockquote><p>Businesses either do, make, or sell things. For service-based businesses like yours, the vast majority of your costs are people costs. So measuring that expense is crucial to a healthy (or otherwise) business.</p>',10)])])}const b=t(s,[["render",r]]);export{f as __pageData,b as default};
